39.   renderContainer,
40.   noChildren,
41.   containerProps,
42.   defaultProps,
43.   ...options
44. }: CesiumComponentOptions<Element, Props, State>): CesiumComponentType<Element, Props> => {
45.   const component: ForwardRefRenderFunction<CesiumComponentRef<Element>, Props> = (props, ref) => {
46.     const mergedProps = {
47.       ...defaultProps,
48.       ...props,
49.     };
50.     // eslint-disable-next-line react-hooks/rules-of-hooks
51.     const [provided, mounted, wrapperRef] = useCesiumComponent<Element, Props, State>(
52.       options,
53.       mergedProps,
54.       ref,
55.     );
56. 
57.     if (noChildren) return null;
58. 
59.     const children = mounted
60.       ? "children" in mergedProps
61.         ? (mergedProps as PropsWithChildren<Props>).children
62.         : null
63.       : null;
64.     const wrappedChildren = renderContainer ? (
65.       <div
66.         data-testid="resium-container"
67.         ref={wrapperRef}
68.         {...(typeof containerProps === "function"
69.           ? containerProps(mergedProps)
70.           : pick(mergedProps, containerProps))}>
71.         {children}
72.       </div>
73.     ) : children ? (
74.       <>{children}</>
75.     ) : null;
76. 
77.     if (provided) {
78.       return <CesiumContext.Provider value={provided}>{wrappedChildren}</CesiumContext.Provider>;
79.     }
80.     return wrappedChildren;
81.   };
82. 
