1. import { Event as CesiumEvent } from "cesium";
2. import {
3.   useEffect,
4.   useRef,
5.   useImperativeHandle,
6.   useState,
7.   useCallback,
8.   useLayoutEffect,
9.   RefObject,
10. } from "react";
11. 
12. import { RootComponentInternalProps } from "./component";
13. import { ResiumContext, useCesium } from "./context";
14. import { EventManager, eventManagerContextKey, eventNames } from "./EventManager";
15. import { includes, shallowEquals, isDestroyed } from "./util";
16. 
17. export type EventkeyMap<T, P> = { [K in keyof P]?: keyof T };
18. 
19. type CreateReturnType<Element, State = any> = Element | [Element, State] | undefined;
20. 
21. export type Options<Element, Props extends RootComponentInternalProps, State = any> = {
22.   name: string;
23.   create?: (
24.     ctx: ResiumContext,
25.     props: Props,
26.     wrapperRef: HTMLDivElement | null,
27.   ) => Promise<CreateReturnType<Element, State>> | CreateReturnType<Element, State>;
28.   destroy?: (
29.     element: Element,
30.     ctx: ResiumContext,
31.     wrapperRef: HTMLDivElement | null,
32.     state?: State,
33.   ) => void;
34.   provide?: (
35.     element: Element,
36.     ctx: ResiumContext,
37.     props?: Props,
38.     state?: State,
39.   ) => Partial<ResiumContext>;
40.   update?: (
41.     element: Element,
42.     props: Props,
43.     prevProps: Props,
44.     context: ResiumContext,
45.   ) => void | Promise<void>;
46.   cesiumProps?: readonly (keyof Props)[];
47.   cesiumReadonlyProps?: readonly (keyof Props)[];
48.   cesiumEventProps?: EventkeyMap<Element, Props>;
49.   otherProps?: readonly (keyof Props)[];
50.   setCesiumPropsAfterCreate?: boolean;
51.   useCommonEvent?: boolean;
52.   useRootEvent?: boolean;
53. };
54. 
55. export const useCesiumComponent = <Element, Props extends RootComponentInternalProps, State = any>(
56.   {
57.     name,
58.     create,
59.     destroy,
60.     provide,
61.     update,
62.     cesiumReadonlyProps,
63.     cesiumEventProps,
64.     otherProps,
65.     setCesiumPropsAfterCreate,
66.     useCommonEvent,
67.     useRootEvent,
68.   }: Options<Element, Props, State>,
69.   props: Props,
70.   ref: any,
71. ): [Partial<ResiumContext> | undefined, boolean, RefObject<HTMLDivElement>] => {
72.   const element = useRef<Element>();
73.   const ctx = useCesium();
74.   const provided = useRef<Partial<ResiumContext> | undefined>(provide ? {} : undefined);
75.   const attachedEvents = useRef<{
76.     [key in keyof Element]?: any;
77.   }>({});
78.   const initialProps = useRef<Props>(propsWithChildren(props));
79.   const prevProps = useRef<Props>({} as Props);
80.   const [mounted, setMounted] = useState(false);
81.   const mountedRef = useRef(false);
82.   const wrapperRef = useRef<HTMLDivElement>(null);
83.   const stateRef = useRef<State>();
84.   const eventManager = ctx?.[eventManagerContextKey];
85. 
86.   // Update properties
87.   const updateProperties = useCallback(
88.     async (props: Props) => {
89.       if (!element.current) return;
90.       const target: any = element.current;
91. 
92.       const propsKeys = Object.keys(props) as (keyof Props)[];
93.       const eventKeys = Object.keys(cesiumEventProps || []) as (keyof Props)[];
94. 
95.       const propDiff = propsKeys
96.         .concat(
97.           (Object.keys(prevProps.current) as (keyof Props)[]).filter(k => !propsKeys.includes(k)),
98.         )
99.         .filter(k => prevProps.current[k] !== props[k])
100.         .map(k => [k, prevProps.current[k], props[k]] as [keyof Props, any, any]);
101. 
102.       const updatedReadonlyProps: (keyof Props)[] = [];
103.       for (const [k, prevValue, newValue] of propDiff) {
104.         if (cesiumReadonlyProps?.includes(k)) {
105.           updatedReadonlyProps.push(k);
106.         } else if (includes(eventKeys, k)) {
107.           const cesiumKey = cesiumEventProps?.[k] as keyof Element;
108.           const eventHandler = target[cesiumKey];
109.           if (eventHandler instanceof CesiumEvent) {
110.             if (typeof prevValue === "undefined") {
111.               // added
112.               eventHandler.addEventListener(newValue);
113.               attachedEvents.current[cesiumKey] = newValue;
114.             } else if (typeof newValue === "undefined") {
115.               // deleted
116.               eventHandler.removeEventListener(prevValue);
117.               delete attachedEvents.current[cesiumKey];
118.             } else {
119.               // updated
120.               eventHandler.removeEventListener(prevValue);
121.               eventHandler.addEventListener(newValue);
122.             }
123.           }
124.         } else if (k !== "children" && !eventNames.includes(k as any) && !otherProps?.includes(k)) {
125.           target[k] = newValue;
126.         }
127.       }
128. 
129.       const em = useRootEvent
130.         ? (provided.current?.[eventManagerContextKey] as EventManager | undefined)
131.         : eventManager;
132.       if (useCommonEvent && em && element.current) {
133.         em.setEvents(useRootEvent ? null : element.current, props);
134.       }
135. 
136.       if (update && mountedRef.current) {
137.         const maybePromise = update(element.current, props, prevProps.current, ctx);
138.         if (
139.           maybePromise &&
140.           typeof maybePromise === "object" &&
141.           typeof (maybePromise as Promise<void>).then === "function"
142.         ) {
143.           await maybePromise;
144.         }
145.       }
146. 
147.       prevProps.current = props;
148.       initialProps.current = props;
149. 
150.       // Recreate cesium element when any read-only prop is updated
151.       if (mountedRef.current && updatedReadonlyProps.length > 0) {
152.         if (process.env.NODE_ENV !== "production") {
153.           console.warn(
154.             `Warning: <${name}> is recreated because following read-only props have been updated: ${updatedReadonlyProps.join(
155.               ", ",
156.             )}`,
157.           );
158.         }
159. 
160.         unmount();
161.         mount();
162.       }
163.     },
164.     [], // eslint-disable-line react-hooks/exhaustive-deps
165.   );
166. 
167.   const mount = useCallback(async () => {
168.     // Initialize cesium element
169.     const maybePromise = create?.(ctx, initialProps.current, wrapperRef.current);
170. 
171.     let result: CreateReturnType<Element, State>;
172.     if (
173.       maybePromise &&
174.       typeof maybePromise === "object" &&
175.       typeof (maybePromise as Promise<unknown>).then === "function"
176.     ) {
177.       result = await maybePromise;
178.     } else {
179.       result = maybePromise as CreateReturnType<Element, State>;
180.     }
181. 
182.     if (Array.isArray(result)) {
183.       element.current = result[0];
184.       stateRef.current = result[1];
185.     } else {
186.       element.current = result;
187.     }
188. 
189.     if (setCesiumPropsAfterCreate) {
190.       await updateProperties(initialProps.current);
191.     } else {
192.       // Attach events
193.       if (element.current && cesiumEventProps) {
194.         const target: any = element.current;
195.         for (const key of Object.keys(initialProps.current) as (keyof Props)[]) {
196.           const eventKey = cesiumEventProps[key];
197.           if (eventKey) {
198.             const e: any = initialProps.current[key];
199.             const eventHandler = target[eventKey];
200.             if (e && eventHandler instanceof CesiumEvent) {
201.               eventHandler.addEventListener(e);
202.             }
203.           }
204.         }
205.       }
206. 
207.       prevProps.current = initialProps.current;
208.     }
209. 
210.     if (provide && element.current) {
211.       provided.current = {
212.         ...ctx,
213.         ...provide(element.current, ctx, props, stateRef.current),
214.       };
215.     }
216. 
217.     const em = useRootEvent
218.       ? (provided.current?.[eventManagerContextKey] as EventManager | undefined)
219.       : eventManager;
220.     if (useCommonEvent && em && element.current) {
221.       em.setEvents(useRootEvent ? null : element.current, initialProps.current);
222.     }
223. 
224.     setMounted(true);
225.   }, []); // eslint-disable-line react-hooks/exhaustive-deps
226. 
227.   const unmount = useCallback(() => {
228.     // Destroy cesium element
229.     if (element.current && destroy) {
230.       destroy(element.current, ctx, wrapperRef.current, stateRef.current);
231.     }
232. 
233.     const em = useRootEvent
234.       ? (provided.current?.[eventManagerContextKey] as EventManager | undefined)
235.       : eventManager;
236.     if (useCommonEvent && em && element.current) {
237.       em.clearEvents(useRootEvent ? null : element.current);
238.     }
239. 
240.     // Detach all events
241.     if (element.current && !isDestroyed(element.current)) {
242.       const attachedEventKeys = Object.keys(attachedEvents.current) as (keyof Element)[];
243.       for (const k of attachedEventKeys) {
244.         const eventHandler: any = element.current[k];
245.         eventHandler?.removeEventListener?.(attachedEvents.current[k]);
246.       }
247.     }
248. 
249.     attachedEvents.current = {};
250.     provided.current = undefined;
251.     stateRef.current = undefined;
252.     element.current = undefined;
253. 
254.     setMounted(false);
255.     mountedRef.current = false;
256.   }, []); // eslint-disable-line react-hooks/exhaustive-deps
257. 
258.   // To prevent re-execution by hot loader, execute only once
259.   useLayoutEffect(() => {
260.     mount();
261.     return () => unmount();
262.   }, []); // eslint-disable-line react-hooks/exhaustive-deps
263. 
264.   // Update properties of cesium element
265.   useEffect(() => {
266.     const propsWC = propsWithChildren(props);
267.     if (mounted) {
268.       if (!shallowEquals(propsWC, prevProps.current)) {
269.         updateProperties(propsWC);
270.         ctx.__$internal?.onUpdate?.();
271.       }
272.     } else {
273.       // first time
274.       prevProps.current = propsWC;
275.       initialProps.current = propsWC;
